import React from "react";
import { FaPlus, FaEdit, FaTrashAlt, FaMicrochip, FaTimes } from "react-icons/fa";
import NameEntityForm from "./NameEntityFormComponent";
import GenericTable from "./GenericTableComponent";

// داده‌ی نمونه — در پروژه‌ی واقعی از API می‌آید
const SAMPLE_DEVICE_TYPES = [
  { id: 1, name: "ساید" },
  { id: 2, name: "یخچال فریزر" },
  { id: 3, name: "دوقلو" },
  { id: 4, name: "فرنچ" },
  { id: 5, name: "لباسشویی" },
  { id: 6, name: "ظرفشویی" },
  { id: 7, name: "کولر گازی" },
  { id: 8, name: "مایکروویو" },
  { id: 9, name: "یخچال و فریزر صنعتی" },
];

// صفحه‌ی مدیریت نوع دستگاه
class DeviceTypeManagementPage extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      deviceTypes: SAMPLE_DEVICE_TYPES,
      isAdding: false, // با کلیک روی دکمه‌ی + این true می‌شه و فرم افزودن باز می‌شه
    };
    this.handleAdd = this.handleAdd.bind(this);
    this.handleCancelAdd = this.handleCancelAdd.bind(this);
    this.handleCreate = this.handleCreate.bind(this);
    this.handleEdit = this.handleEdit.bind(this);
    this.handleDelete = this.handleDelete.bind(this);
  }

  handleAdd() {
    this.setState({ isAdding: true });
  }

  handleCancelAdd() {
    this.setState({ isAdding: false });
  }

  handleCreate(name) {
    const trimmed = name.trim();
    if (!trimmed) return;

    // TODO: اینجا باید API ایجاد نوع دستگاه صدا زده بشه و بعد از جواب موفق state آپدیت بشه
    // مثال:
    // const created = await api.createDeviceType({ name: trimmed });
    // this.setState((prev) => ({
    //   deviceTypes: [...prev.deviceTypes, created],
    //   isAdding: false,
    // }));

    this.setState((prev) => ({
      deviceTypes: [
        ...prev.deviceTypes,
        { id: Date.now(), name: trimmed },
      ],
      isAdding: false,
    }));
  }

  handleEdit(id) {
    // مسیر ویرایش نوع دستگاه بعداً وصل می‌شود
    console.log("ویرایش نوع دستگاه:", id);
  }

  handleDelete(id) {
    // TODO: قبل از حذف از state، باید API حذف صدا زده بشه
    this.setState((prev) => ({
      deviceTypes: prev.deviceTypes.filter((d) => d.id !== id),
    }));
  }

  render() {
    const { deviceTypes, isAdding } = this.state;

    // حالت افزودن: همون فرم عمومیِ نام‌محورمون رو نشون می‌دیم
    if (isAdding) {
      return (
        <div className="conta min-vh-100 position-relative">
          <button
            type="button"
            onClick={this.handleCancelAdd}
            className="btn btn-light rounded-circle border p-2 d-flex align-items-center justify-content-center position-absolute"
            style={{ width: 36, height: 36, top: 16, left: 16, zIndex: 1 }}
          >
            <FaTimes size={14} />
          </button>

          <NameEntityForm
            title="افزودن نوع دستگاه"
            fieldLabel="نام"
            icon={<FaMicrochip className="text-secondary" size={18} />}
            submitLabel="ثبت"
            onSubmit={this.handleCreate}
          />
        </div>
      );
    }

    const columns = [
      { key: "name", label: "نام", headerClassName: "text-dark" },
      {
        key: "edit",
        label: "ویرایش",
        width: "0.6fr",
        headerClassName: "text-primary",
        render: (row) => (
          <button
            type="button"
            onClick={() => this.handleEdit(row.id)}
            className="btn btn-light border-0 p-1"
          >
            <FaEdit className="text-secondary" size={18} />
          </button>
        ),
      },
      {
        key: "delete",
        label: "حذف",
        width: "0.6fr",
        headerClassName: "text-primary",
        render: (row) => (
          <button
            type="button"
            onClick={() => this.handleDelete(row.id)}
            className="btn btn-light border-0 p-1"
          >
            <FaTrashAlt style={{ color: "#f08a72" }} size={17} />
          </button>
        ),
      },
    ];

    return (
      <div>
        <div className="container px-3 pt-4 pb-5" style={{ maxWidth: 480 }}>
          <div className="d-flex align-items-center justify-content-between mb-4">
            <h1 className="fs-6 fw-semibold text-dark m-0">مدیریت نوع دستگاه</h1>
            <button
              type="button"
              onClick={this.handleAdd}
              className="btn btn-light rounded-circle border p-2 d-flex align-items-center justify-content-center"
              style={{ width: 40, height: 40, transition: "background-color 0.15s ease" }}
            >
              <FaPlus size={16} />
            </button>
          </div>

          <GenericTable columns={columns} rows={deviceTypes} />
        </div>
      </div>
    );
  }
}

export default DeviceTypeManagementPage;
